INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1123492-che401', 'stk-w_a_g_e_h', 'CHE 401', 'info', '{"desc": "^\n,وعليكم السلام\n\nالكورس الحين عندي . الكورس من وجهه نظري يبيله شغل ويعتمد على الدكتور الى بتنزل عنده\n\nالكورس بشكل عام يتكلم عن كيف تتحكم بالكيمكل بروسس بشكل عام والداينمك\n\nيعني مثلا لو بنزيد درجه حراره ريكتر كم الوقت الازم ليبدا التغير للاوت بوت وشغلات الكونترول كلها وكيف تدخل المعادلات في الكونترول عشان تتحكم فيها ومن هالشغلات\n\nيبيلها شغل ماث كثير\n\nبالنسبه للفيزكل كمستري ماده غثيثه وطويله ويبيلها حفظ وفهم\n\nانصحك تنزل 401", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-401-process-dynamics-and-control/120656/2", "user": "W_a_G_e_H", "ts": 1353837241000, "tid": 120656, "pn": 2}}', 1353837241000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1129671-che401', 'stk-smsooom5', 'CHE 401', 'info', '{"desc": "بالنسبة لي\n\nاصعب كورس في التخصص …واكتر كورس يحتاجله شغل وتعب\nتحتاج تفهم كل جزئية فيه …\n\nوبالنسبة لفقير او الشمري\nفقير يشررررح وتفهم معاه … بس طريقة شرحه صعبة شوية وتحتاج تركز معاه\nواسئلته صعبة < على قد شرحه\n\nالشمري … حسب كلام الشباب\nحبوب ومتساهل واسئلته سهلة\n\nوبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-401-process-dynamics-and-control/120656/5", "user": "SmsoOom5", "ts": 1354520108000, "tid": 120656, "pn": 5}}', 1354520108000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1318729-che401', 'stk-user8690', 'CHE 401', 'info', '{"desc": "che 401- 131\nاخذت المادة مع الدكتور نعيم فقير. المادة صراحة زي ما قالوا الشباب يبيلها شغل لكن مو ذيك الصعوبة الي كنت متخيلها قبل ماخذ الكورس ونفس الوقت هذا لا يعني انك تسحب عليها لانك اذا سحبت هي بعد بتسحب وبتشوف درجات في الحضيض 🤪\n\nالزبدة المادة ميجرين وفاينال وكلاس وورك عليه 25 بالمية والتوزيع كالتالي\nmajor 1 20%\nذاكر الكتاب مع الامثلة المحلولة في الكتاب واسئلة الهومورك (افهم لا تحفظ) ان شاء الله وضعك في السليم\nmajor 2 20%\nنفس طريقة مذاكرة الميجر الاول ونسبيا انا اشوفه اسهل من ميجر 1\nclass work 25%\nلاتفرط فيها لانها ممكن تغير كثير من درجتك النهائية. ملاحظة: الدكتور عادة يعطي كويز واحد فقط طول السمستر وعليه 8 % وغالبا على ماتيريال ميجر 1\nfinal 35%\nالفاينال كان فقط على الماتيريال الجديد مع ان الدكتور ماقالنا بشكل واضح. الفاينال كان متوسط وبالنسبة للمذاكرة انا بالنسبة لي نفس مذاكرة الميجرين\n\nالقريدات\nدرجاتي في الميجرين كانت تحت الافرج بكثير\nmajor 1\n39 (avg is 51)\nmajor 2\n45 (avg is 71)\nلكن الكلاس وورك كان مضبوط والفاينال حليت زين. طلعت ب C ( كنت متوقع اقل )\n\nالمياجر كانت كومون والفاينال كل دكتور حط فاينل خاص فيه.\nوسلامتكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-401-process-dynamics-and-control/120656/9", "user": "user8690", "ts": 1389611885000, "tid": 120656, "pn": 9}}', 1389611885000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1319289-che401', 'stk-chemist', 'CHE 401', 'info', '{"desc": "جودة المقرر بشكل عام:\nمهم جدا للمهندس الكيميائي ويعتبر في أغلب الجامعات من الكورسات الأساسية لبرنامج الهندسة الكيميائية. وهو يتكلم بشكل عام عن دايناميكا العمليات والتحكم التحكم فيها.\n\nالمواضيع التي يغطيها المقرر:\nChapter 1\nهذا التشابتر عبارة عن مقدمة في Process Dynamics & Control يشمل على بعض التعاريف لبعض المصطلحات وأهمية التحكم في العمليات في تخفيض التكلفه الإقتصادية وفي تحسين المنتج.\nChapter 2\nفي هذا التشابتر تحول الأنظمة الكيميائية من مفاعل أو خزان أو برج فصل إلى معادلات رياضية بواسطة ( Mass Balance ) و ( Energy Balance ) معا. فراح تستخدم وبكثرة اللي درسته في CHE 201 & CHE 203 وراح تستخدم أيضا Degree of Freedom Analysis\nChapter 3\nالهدف من هذا التشابتر هو تحويل المعادلات الرياضية إلى ( Transfer Function ) بواسطة ( Laplace Transformation ). فكل نظام كيميائي في تشابتر 2 راح تحوله إلى Transfer Function في تشابتر 3.\nChapter 4\nتدرس في هذا الجزء السلوك الحركي لنظام سواء كان من الدرجة الأولى أو الثانية عندما يتعرض إلى تغيير مفاجئ طارئ عليه. أيضا تدرس أنواع التغييرات من ( Step change ) و ( Impulse Change ) و ( Rectangular Change ) و ( Sinusodial Change ).\nChapter 5\nتدرس في هذا التشابتر الأنظمة الكيميائية المعقدة ( أكبر من الدرجة الثانية) وسلوكها عن اجراء عليها أي تغيير مفاجئ. أيضا تدرس معامل التخميد Damping Coefficient (زيتا Zeta) ودراسة استقرارية النظام ( system Stability ).\nChapter 6\nتدرس فيه عن Feedback controller وانواعه المختلفة من PID Controller, P Controller, PI Controller, PD Controller والمعادلات لكل نوع منهم ومزايا كل نوع.\nبقية الكورس:\nتدرس عن تصميم PID Controller و تدرس أيضا عن Control system Instrumentation + Frequency analysis إلخ …\n\nتقيمي للكورس:\nمن أصعب كورسات الهندسة الكيميائية اللي مرت علي. فيه رياضيات بشكل كبير جدا وفيه أعداد خياليه Complex numbers وفيه استخدام كبير للدوال المثلثية Sin & Cos في تفسير سلوك النظام فراح يشكل لك هاجس كبير جدا في الفصل.\n\nالمذاكرة الصحية للكورس:\nكانت أموري في السليم وكنت اجيب درجات حلوه في المياجر لأني كنت أذاكر الكتاب وأحل أسئة الواجب وما شابهها من أسئلة الكتاب وتقدر تستعين بالمانيوال سلوشن علشان تشيك على حلك. طبعا فيه سلايدات للدكتور شمس الضحى ولكن في وجهة نظري لا أرى انها تغني أو تسمن من جوع من ناحية الفهم فأشوف انها تصلح فقط للمراجعه.\n\nالكتاب المقرر:\nSeborg, D.E., Edgar, T.F. and Mellichamp, D.A., “Process Dynamics and Control”, John wiley & Sons, 3rd edition, 2011.\n\nتقييمي للكتاب:\nممتاز جدا ولكن فيه عيبين:\n1) فيه تفاصيل زايدة ما يحتاجها الطالب.\n2) نقص في توفر الأمثلة والتمارين الكافية في بعض السكاشن.\n\nانتهى تقييمي 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-401-process-dynamics-and-control/120656/10", "user": "Chemist", "ts": 1389745198000, "tid": 120656, "pn": 10}}', 1389745198000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1372751-che401', 'stk-_chemical', 'CHE 401', 'info', '{"desc": "**term 132** أخذت المادة مع د. نعيم فقير وكان أخر ترم له , الكورس أشوفه من أهم كورسات التخصص ويبيله متابعة أول بأول الكتاب أشوفه ممتاز بشكل عام وسيء بشرح بعض النقاط مجملا الكتاب كويس , القسم مسهل الكورس بشكل كبير الهوموركات مهمة بهالكورس إذا حليتها وفهمتها وضعك سليم بالمياجر والفاينل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-401-process-dynamics-and-control/120656/13", "user": "_chemical", "ts": 1401213345000, "tid": 120656, "pn": 13}}', 1401213345000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1450052-che401', 'stk-_3111', 'CHE 401', 'info', '{"desc": "سمستر 152 - مع الدكتور قدوس\n\nجودة المقرر بشكل عام: الكنترول شي مهم وان كان طريقة التدريس ليست ممتازة\nالمواضيع التي يغطيها المقرر: كيمست كفى ووفى مافي شي تغير، بس أحب استدرك أنه في رأيي الصعوبة مو في الماث بقدر ما هي الكونسيبت، لأن هذه المادة ما تشبه اي مادة ثانية في التخصص بل منفصلة عنهم وقريبة من تخصصات ثانية (تخيلوا أنه نفس المادة ونفس الكتاب يدرسوه طلاب هندسة التحكم في كورس ليفيل 4! cise 418 ) الماث الموجود هو عبارة عن بارشل فراكشن (ماث 102) + لابلاس ترانزفورمز (مو صعب) وباقي المهارات الجبرية المعروفة\nالكتاب المستخدم للمقرر: Process Dynamics and Control by Dale E. Seborg\nالأسئلة والأمثلة المستخدمة في المقرر: المصدر اللي عندك هو أسئلة الواجبات والكويزات غالبا منها واذا مو منها يخليه الدكتور تيك هوم وشي قريب يجي في الميجر\nمدى فائدته في الناحية التطبيقية: الكنترول مهم في المصانع ودرسنا تطبيقاته في 409 لكن بصراحة ما أدري اذا كل التفاصيل اللي ما تخلص بتكون موجودة في الواقع\n\nاضافة: الدكتور الوحيد في القسم المتخصص في الكنترول هو الدكتور عبدالله الشمري ومو دايما يدرس كونه مشغول مع شؤون الطلاب. قدوس ومحمد حسين تخصصهم المفاعلات والمحفزات ومع هذا ماسكين الكورس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-401-process-dynamics-and-control/120656/14", "user": "_3111", "ts": 1463952799000, "tid": 120656, "pn": 14}}', 1463952799000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467017-che401', 'stk-k_94', 'CHE 401', 'info', '{"desc": "جودة المقرر بشكل عام\n\nالصراحة ما هو صعب ولكن ما له داعي وما هو شغلنا الكميكلز … لكن على كلام الدكتور ندرسه عشان نعرف الlanguage اذا تكلمنا مع المهندسين بالمصنع ولكن ما بنستفيد منه كثير بالواقع\n\nالكتاب المستخدم للمقرر\nامثلته قليله نسبيا , ولكن الدكتور كان المياجر والكوزات يجيبها مشابهه للامثلة … ما عدا الفاينل تغير شوي\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nجيدة جزئيا ولكن ذاكر اسئلة الهومورك فيه سلوشن للنسخة الثانية من الكتاب\n\nمدى فائدته في الناحية التطبيقية\n\nما له فايدة زي ما ذكرت سابقا , الكورس ما كان صعب ابدا والدكتور عبدالله الشمري جزاه الله خير سهله لنا زيادة\n\n----\n\nملاحظة : ممكن تشوف ناس تقول هذا كورس سهل وناس تقول صعب , السبب يرجع للدكتور لانه بالعادة كل دكتور له مياجره وفاينله زي ما حصل الترم هذا مع الدكتور عبدالله الشمري وقدوس كل واحد له مياجره وفاينله لطلابه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-401-process-dynamics-and-control/120656/16", "user": "K_94", "ts": 1485380233000, "tid": 120656, "pn": 16}}', 1485380233000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1486839-che401', 'stk-user9534', 'CHE 401', 'info', '{"desc": "الكورس يعتمد بشكل كبير على الدكتور، كل دكتور له طريقته بالتعامل بهذا الكورس\nلكن بشكل عام الكونسيبت ماهو صعب الفهم، الكتاب مايشرح بشكل ممتاز فلذلك أنصح بالسلايدات\n\nفي الرابط المانيوال سلوشن للكتاب+ سلايدات\n401 files - Download - 4shared", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-401-process-dynamics-and-control/120656/17", "user": "user9534", "ts": 1517082621000, "tid": 120656, "pn": 17}}', 1517082621000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1271360-che401', 'stk-user6882', 'CHE 401', 'info', '{"desc": "مساء الخير جميعا…\n\nالكل يعرف ان الاسبوع القادم هو اسبوع اختبارات لجميع المواد وكل دكتور يريد ان يختبر طلابه قبل الاجازة حتى يتمكن من ارسال تقرير عن مستوى الطلاب \" midterm warning\" الى المسجل. وكما تعلمون ان البعض لديه اختبارات متوالية مدمجة وسط الهوموركات والكويزات واللابات …فمن خلال هذا الموضوع نرى نسبة الذين يريدون تاجيل الاختبار الى بعد العيد من غيرهم وبالتالي نستطيع اخبار الاساتذة بهذه النسبة وعلى اثرها يتم القرار.\n\nملاحظة: انا لا اقصد الطلاب الذين عندهم اختبارين يفصل بينهم مدة قد تصل الى يوم مثل الاحد والثلاثاء او السبت والاثنين.\nبل اقصد الطلاب الذين عندهم اختبارات /السبت -الاحد-الاثنين او الاحد الاثنين -الثلاثاء متتالية\nفارجوا من الجميع التفاعل لان هذا الموضوع مهم للجميع\n\nقال الرسول صلى الله عليه و سلم :\" لا يؤمن احدكم حتى يحب لاخيه مايحب لنفسه\"", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-401/150443/1", "user": "user6882", "ts": 1380832666000, "tid": 150443, "pn": 1}}', 1380832666000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1271256-che401', 'stk-user4254', 'CHE 401', 'info', '{"desc": "١) لا ما تأجل، فقط طلاب اللي عندهم me راح يختبرون بعد العيد\n٢) الميجر والفاينل كلها كومون\n٣) لا أعلم الصراحة، ولكن أظن كل دكتور له أفرج خاص بشعبه مثل ما صار في ٣٠٦\n٤) والله يالغالي أنا ماشي مع نوت الدكتور الشمري، والكتاب أرجع له قليل في بعض الأمثلة اللي شرحها الدكتور + أسئلة الهوم وورك\n\nبالتوفيق يا عزيزي وأتمنى أكون أفدتك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-401/150412/2", "user": "user4254", "ts": 1380809585000, "tid": 150412, "pn": 2}}', 1380809585000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4656-che401', 'stk-user4656', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f98540", "n": "Dr. Naim M Faqir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "che401\nبالنسبة للمادة المادة تحتاج إلى شغل ومذاكرة أول بأول لكن ماهي بصعبة …\nبالنسبة للدكتور غير منظم وغير مرتب وسريع جدا في الشرح لكنه فاهم وشارب المادة شرب …\nبالنسبة لي أنا كانت تعجبني طريقة شرحه وأقدر أفهم عليه ولله الحمد لكن فيه مجموعة من الشباب\nماكانوا مبسوطين من الدكتور من ناحية الشرح والسبب هو التنظيم والسرعة ,\nالتحضير أغلب الأحيان مايحضر , الكويزات اعطانا واحد بس , التصحيح عادي و أحيانا يخصم ع أشياء غبية ماتسوى في نظري …\nالدكتور ضعيف في التواصل أرسلت له أكثر من مرة ولايرد للاسف …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1162307-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naim-m-faqir/98540/20", "user": "user4656", "ts": 1357921674000, "tid": 98540, "pn": 20}}]}', 1357921674000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-che401', 'stk-chemist', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f98540", "n": "Dr. Naim M Faqir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 401 Term 131\nالتحضير:\nكل حصة وينادي بـSN وأشوف ان ماعنده مشكله بالتأخير ولكن ما أدري والله هل يحضرك بشكل عادي أو يحضرك ليت.\n\nالشرح:\nما شاء الله عليه فاهم المادة صح والمادة أصلا هي قلب تخصصه ( Control Engineer ) ويكتب نوت مفيد بس للأمانة ما كنت أكتب معه لأن خطه مو واضح في بعض الأحيان. أما في توصيل المعلومة والشرح فأشوف أنه وسط لاهو ممتاز جدا ولا هو بالسئ والمادة أصلا ماتساعد على الفهم. طول السمستر الطلاب يسلكون له 😆 يقول لنا أنتوا فاهمين أو ( Are you following me ? ويردون عليه الشباب بصوت واحد مع تحريك الرأس للأسفل يس وحنا ماندري وش الطبخه. في نصف الفصل شكله حس ان الطلاب يسلكون له فقال نفس جملته الشهيره Are you following me ? ردوا الشباب نفس الرد ونفس حركت الرأس يس قال وهو مبتسم Any how 😆 يعني درى ان حنا نسلك له. فيه عليه سلبيتين الأولى في بعض الأحيان مايتبع الكتاب أو السلبس ومايحل مسائل واجد والثانية انه يعصب بعض الأحيان إذا الطالب مافهم أو كثر عليه الأسئله 😆.\n\nالكوزات:\nطول الفصل عطانا كويز واحد او اثنين وكانت سهلة\n\nالمياجر:\nكانت كومن بينه وبين الدكتور عبدالله الشمري وكانت سهلة مو على قدر صعوبة الكتاب وكانت من أسئلة الهوم ورك تطبيق مباشر.\n\nالفاينال:\nالفاينال مو كومون ولا اقدر احكم على صعوبته لأني ما كنت مذاكر أصلا.\n\nاضافات:\nالدكتور حبيب جدا وخلوق وكنت أعتبره بصراحه قدوة لي وأيضا مثل أبوي والله يوفقه ويسعده.\n\nالقريد النهائي للدكتور:\nB", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1319298-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naim-m-faqir/98540/25", "user": "Chemist", "ts": 1389747429000, "tid": 98540, "pn": 25}}]}', 1389747429000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8581-che401', 'stk-user8581', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f98649", "n": "Dr. Sami El-Ferik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CISE 418 - TERM 152\n\nالتحضير : غالباً نهاية الكلاس لكن إذا لاحظ الطلاب يتأخرون كثير يبتدي يحضر اول 5 دقايق .\n\nطريقة الشرح :\n- ممتاز ويعطيك مقدمة للموضوع ويتدرج مع الطلاب في الشرح يعني احيانا يشرح نقطة معينة و إذا فهمتها اكيد راح يجي في بالك سؤال معين فهو يعتمد على هذا الاسلوب احيانا عشان ينتقل لنقطة ثانية ولها علاقة بالموضوع.\n\n- يعطي امثلة واسئلة في المحاضرة ويناقشها مع الطلاب فأنصح الي ينزل معاه إنه يكتب ويركز معاه وإذا سويت كذا راح تطلع بقريد ممتاز إن شاء الله .\n- السلبية الوحيدة في شرحه هي إن إذا كتب مثال على السبورة وبعد مايحله يقعد يغير في المثال فإذا كنت تكتب وراه راح تتعب ومب يمديك تكتب المثال بعد التعديل في هذي الحالة حاول تفهم السؤال بعد التعديل ولا تكتبه لأنه ماراح يمديك وماتقدر تركز معاه فتحس روحك ضايع في المحاضرة .\n- غالبا يأخذ المحاضرة كاملة .\n\nالكويزات : من الي يشرحه في الكلاس واحيانا من الهوموركات وبشكل عام كويزاته سهلة لكن أحيانا يخلي فيها تريك بسيط فأفضل مصدر للمذاكرة : هي نوتاته + الهومورك وركز في الكويز عشان لاتضيع منك 25 درجة . تقريبا عطانا 6 او 5 كويزات وحذف أسوء واحد منها .\n\nالمياجر: الكورس فيه ميدتيرم وكان سهالات تقريبا نفس الكويزات والاسئلة الي في النوتة .\nالفاينلات : مشابه للكويزات والميدتيرم وتقريبا كان 4 اسئلة .\nالقريد النهائي:\n- أنصح فيه للي يركز بالكلاس ويقدر يكتب في نفس الوقت اما اذا كنت من الشباب الي مايقدر يكتب ونفس الوقت ينتبه للدكتور راح تتعب معاه .\n\nكأخلاق من أفضل الدكاترة الي شفتهم في الجامعة ومتعاون جداً أعطيه B+ كشرح.\n- ما اعرف نظامه في القريدات لكن اتوقع نفس كلام العضو (ملك العز) ^^^^\n\nالصوت: واضح والاكسنت ممتاز .\n\nإضافات :\n- الهوموركات كانوا 4 وبعض الاسئلة جات في الكويزات .\n\n- السلوشن مانول. ( طبعا الكتاب المستخدم هو نفس الكتاب لكورس che401 على ما اعتقد + تأكدوا من ترتيب الشباتر لأن السلوشن للنسخة الثانية والكتاب هو النسخة الثالثة )\nhttp://www.stkfupm.com/forum/showthread.php?t=99569\n- السلايدات ( هي سلايدات الكتاب )\nhttps://chemengr.ucsb.edu/~ceweb/faculty/seborg/teaching/slides.html", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450024-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sami-el-ferik/98649/15", "user": "user8581", "ts": 1463929340000, "tid": 98649, "pn": 15}}]}', 1463929340000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6661-che401', 'stk-user6661', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f99335", "n": "Dr. A Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "che 401 - ترم 122\n\nالتحضير (احيانا) …\n\nمستوى الشرح متوسط , لكنه يعطيك الزبدة ومسهل المادة …\n\nمتعاون مع الطلاب بالتصحيح ,\n\nوبالقريدات افضل من غيره …\n\nانصح فيه , بالتوفيق 🌹 …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1230134-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-shammari/99335/9", "user": "user6661", "ts": 1369941436000, "tid": 99335, "pn": 9}}]}', 1369941436000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hexane-che401', 'stk-hexane', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f99335", "n": "Dr. A Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه CHE 401 في ترم 112\n\nالتحضير :\nيحضّر يومياً, والتأخير يمشّي لكن انتبه تاخذها عادة\n\nطريقة الشرح :\nشرح مبسّط وسهل … من سلايدات\nلكن ميزة السلايدات انها كانت تقريبا رؤوس أقلام … فكان يستعرض رؤوس الأقلام ويشرحها للطلاب … ويكتب على السبورة لتوضيح أكثر للأفكار\n\nنصييييحة أخويية خاااااصة في هذي المادة بالذات (CHE 401) … حاااول انك ما تطلع من الكلاس الا وانت فاهم الدرس … اذا ما فهمت الدرس كويس … روح للدكتور في المكتب, وما راح يقصّر معك. هو ما شاء الله عليه خلوق ويقدّر الطالب اللي يجيه للمكتب\n\nالكويزات :\nمتوسطة مائلة للسهولة\n\nالمياجر:\nمتوسطة الصعوبة و ما يجيب أصعب من أسئلة الكوزات والهوموركات (عدا آخر سؤال), لذلك أنصح وبشدة انك تحل الواجبات بنفسك (بدون نقش 😉 ) وهذا بيفيدك كثييير في فهم المادة … بالنسبة للسؤال الأخير من الإختبار … يحط فيه شوية بهارات 🤠 … طبعا عشان يفرق بين اللي يذاكر بعمق وبين اللي يذاكر مذاكرة مشّي حالك 😲\n\nالفاينلات :\nإختبار شامل لجميع الشباتر … لكن يحذف شابترين أو ثلاثة < ناسي كم بالزبط\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح\n\nإضافات :\nهذا الدكتور … دكتور في الأخلاق والتعامل 👍\nفلّاوي ويحب يمزح مع طلابه\nنززل معاه وانت مغمض زي كذا ~_~ 😆 < احس اني سامج هاليومين مدري ليه 😭", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1246652-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-shammari/99335/11", "user": "HeXaNe", "ts": 1374103861000, "tid": 99335, "pn": 11}}]}', 1374103861000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9221-che401', 'stk-user9221', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f99335", "n": "Dr. A Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che 401 term 141\n\nالدكتور والله من جنبها في الشرح ما يعرف يوصل المعلومة ويكتب أشياء ع السبورة ما تدري هو دريفيشن ولا برووف ولا اقزامبل باختصار شرحه مو مرتب نهائياً … وأيضاً مو متساعد في توضيح طريقة الاختبارات بعكس د. شمس الضحى اللي يعطي أسئلة توتوريال مهمة ويوضح بعض الشغلات بخصوص الاختبارات اللي بدوره يساعد الطلاب على إنهم يأدون بشكل جيد في الاختبار", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1414477-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-shammari/99335/14", "user": "user9221", "ts": 1416615528000, "tid": 99335, "pn": 14}}]}', 1416615528000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-aatmah-che401', 'stk-aatmah', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f99335", "n": "Dr. A Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 401\nبنود التقييم :\n\nالتحضير : بالأسماء ينادي آخر الكلاس\nطريقة الشرح : جيده ويراجع الدروس الماضية مع بداية كل محاضرة ويعطيك زبدة المنهج واسئلته قد شرحه\nالكويزات : متوسطة\nالمياجر: متوسطة وغالباً يجي كم سؤال من أسئلة الكتاب\nالفاينلات : سهالات\nالقريد النهائي: B+\nالصوت: واضح\nإضافات محترم وخلوق وفاهم الطلاب ويقدر اللي يقدره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1465928-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-shammari/99335/16", "user": "AATMAH", "ts": 1483805653000, "tid": 99335, "pn": 16}}]}', 1483805653000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-k_94-che401', 'stk-k_94', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f99335", "n": "Dr. A Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE401 - Term 161\n\nالتحضير : الترم هذا تقريبا بس حضر اربع مرات او 5 , ما يدقق عالتاخير في حال انه قرر يحضر 😆 … التحضيرالترم ئا كان بعد اول اسبوع وبعد ميجر 1\n\nطريقة الشرح : بالبداية يتكلم عن الموضوع بشكل عام واهميته بعدها يحل الامثلة بالكتاب حل تفصيلي وممتاز\n\nالكويزات : اختبرنا 3 كوزات كلها كانت سهله جدا ما عدا واحد متوسط\n\nالمياجر: مياجره كانت جدا سهله وكلها من الامثلة او الهوموورك , بس سؤال واحد ممكن يكون متوسط مائل للصعوبة , افرج ميجر 1 كان 75% وميجر 2 كان 83%:eek-28:\n\nوكلها كانت مسائل بدون كونسبت\n\nالفاينلات : الفاينل الصراحة جدا صعب ولا يقارن بالمياجر وجا فيه اسئلة كثييير عن الكونسبت ( ريتن مو MCQ ) وانا متاكد انه الفاينل هو اللي نزل قريدي وانا الصراحة قصرت نوعا ما بمذاكرته\n\nالقريد النهائي: الدكتور يستاهل A+++ بالاخلاق ما قصر معنا بشي والمياجر خلانا احنا نحدد مواعيدها ومتفهم جدا لمواعيد الكوزات وتسليم الهوموورك والاسايمنتس\n\nالصوت: ضعيف نوعا ما ,\n\nإضافات : الدكتور اعسر يعني لو قعدت بالجهة اليمنى للكلاس ما حتقدر تشوف وش يكتب الا اذا خلص , واعاتب الدكتور حقيقة انه ما اعطانا الكلاس وورك كامل ولا اعطانا درجات الفاينل ولا فرصة اننا اصلا نراجعه بعد الفاينل وحط القريد دايركت بالفاينل , لكن للاسف متعودين هذا الشي من قسمنا معظم الدكاتره يسوون هالحركة …\n\nاللي يبي يرتاح بالترم وما يشيل هم المادة انصحه ينزل مع الدكتور يبسط المادة عليك تخليها اخف مادة عليك بالترم\n\n…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467019-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-shammari/99335/17", "user": "K_94", "ts": 1485381686000, "tid": 99335, "pn": 17}}]}', 1485381686000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a-alajmi-che401', 'stk-a-alajmi', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f99335", "n": "Dr. A Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "172- CHE 401\nبنود التقييم :\n\nالتحضير : بالأسماء ينادي آخر الكلاس واحيانا أول الكلاس ( ويمشي المتأخرين)\nطريقة الشرح : يراجع الدروس الماضية مع بداية كل محاضرة وبعدين يستعرض اهداف المحاضرة ويحاول يوصل المعلومة بأسهل طريقة ممكنة\nالكويزات : متوسطة\nالمياجر: متوسطة وعلى قد شرحه\n\nالقريد النهائي: A+\nالصوت: واضح\nإضافات :\nالله يوفقه دنيا و اخره الدكتور خلوق ومتعاون لاقصى درجة , نزل عنده وانت مغمض", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1491392-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-shammari/99335/18", "user": "A-Alajmi", "ts": 1524569165000, "tid": 99335, "pn": 18}}]}', 1524569165000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-che401', 'stk-khdsa2022', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f99335", "n": "Dr. A Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : عبدالله الشمري\nالمادة: CHE 401\nby whats app\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : يحضر كل يوم\nطريقة الشرح : ضايع و احيانا يوصل الفكرة واحيانا لا، يشرح من سلايداته واللي هي مختصرة المنهج بشكل كبير مرة.\nالكويزات : سهلة\nالمياجر: يجيب اسألة سهلة وسؤال مفاجأة. سؤال المفاجأة أحيانا يكون من برا اللي يشرحه.\nالفاينلات : كان سهل\nالقريد النهائي: B\nالصوت: يجيب النوم\nإضافات :\nالدكتور حبيب بس عليه حركات لعب شويتين، مسهل المادة و مخففها ولا هي المفروض اصعب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518763-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-shammari/99335/19", "user": "Khdsa2022", "ts": 1578210118000, "tid": 99335, "pn": 19}}]}', 1578210118000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmad_che-che401', 'stk-ahmad_che', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f99335", "n": "Dr. A Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE401\nالتحضير : بداية الكلاس\nطريقة الشرح :سلايدات ويشرح بالكلام شرحه حلو لكن بالنسبة لي عيبه انه يجيب امثلة كثير منها امثلة بالحياة وماهي بالتخصص لكن شرحه ممتاز جدا لكن ركز معه\nالكويزات :سهلة\nالمياجر:متوسطة\nالفاينلات :متوسط الى سهل\nالقريد النهائي:ِ+A\nالصوت:واضح\nإضافات : الدكتور قمة بالاخلاق وحبيب ودايم مبتسم لكن يكره اللي يتكلمون بالكلاس ولايركزون معهز ركز معه وشارك ولا تغيب ويعطيك بونص.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522339-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-shammari/99335/21", "user": "ahmad_CHE", "ts": 1590361793000, "tid": 99335, "pn": 21}}]}', 1590361793000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10077-che401', 'stk-user10077', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f115327", "n": "Dr. Mohammad Hossain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله\n\nCHE 401 - Term 151\nلتحضير : ورقة تمر على الطلاب بداي كل محاضرة و ما يدقق ع التاخير\n\nطريقة الشرح : الكونسبت ما تستفيد منه حل مسائل ممتاز ملخبط ويلخبط الطلاب\n\nالكويزات : من الهوموورك\n\nالمياجر: اسئلته حلوه لكن مو سهله\n\nالفاينلات : متوسط , مناسب\n\nالقريد النهائي: C\n\nالصوت: مناسب\n\nإضافات :\nانتبه لا تناقشه لا يحقد عليك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1444959-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-hossain/115327/25", "user": "user10077", "ts": 1458998550000, "tid": 115327, "pn": 25}}]}', 1458998550000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_fauzi-che401', 'stk-abo_fauzi', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f115327", "n": "Dr. Mohammad Hossain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 401 - Term 162\n\nالتحضير : ورقة تمر على الطلاب وتقعد عندهم طول وقت الكلاس … ما يدقق عالتأخير\n\nطريقة الشرح : الصراحة طريقة شرحه مرة ما عجبتني حسيته مرة ضايع في المادة ومو مدركها … كان فيه عشوائية في الشرح بالذات نهاية الترم تحسه بس يبغا يخلص المنهج بأي طريقة … هو عنده سلايدات بس غالباً ما يشرح منها غالباً يشرح ويحل عالسبورة والمادة شبه صعب تقلبها سلف ستدي بحيث انها تعتمد على شرح الدكتور في الكلاس بشكل كبير\n\nالكويزات : 3 كويزات بسيطة تكون من أسئلة الهومورك وفي نهاية الترم أعطانا كويزين بونص\n\nالمياجر: الترم ذا درسها معاه الدكتور قدوس … مياجرهم غالباً تكون صعبة وفي كل ميجر سؤال أو اثنين لازم تكون فاهم مزبوووط عشان تحله ولا ماراح تقدر تحله\n\nالفاينلات : الفاينل جانا حرييييقة لدرجة انو الآفرج حق الفاينل طلع حوالي 38 من 100\n\nالقريد النهائي: C\n\nالصوت: واضح جداً\n\nإضافات :\n- نظام الكويزات عند الدكتور open discussion يعني كانه ورقة عمل تحلها مع باقي الشباب وسط الكلاس\n-الدكتور ما أنصح بيه في الـ401 الصراحة … مو مرة سيء لكنه مو مدرك المادة بشكل كبير زي الـ 300 والـ 304\n- الشباب كانوا يقولوا انو الدكتور يزبط في القريدات وانو الآفرج عنده B لكن الترم ذا ما شفنا الشيء ذا للأسف … يعني القريد اللي تتوقعه غالباً هو اللي بتاخذه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474256-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-hossain/115327/30", "user": "Abo_Fauzi", "ts": 1496263307000, "tid": 115327, "pn": 30}}]}', 1496263307000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_3111-che401', 'stk-_3111', 'CHE 401', 'doc', '{"docs": [{"id": "stk-dr-f172453", "n": "Dr. Quddus Mohammad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "che 401 - 152\nالتحضير : ورقة تعدي والوضع جدا تسليك\nطريقة الشرح : ما يعرف يشرح مطلقا، غير مرتب وجرب كل شي وما ضبطت معه مرات سلايدات ومرات يكتب نوت ومرات يبغى يكتب على الوورد! في مفاهيم جدا بسيطة يطول فيها مرة وبالمقابل في أشياء أساسية ما يعرف يشرحها ببساطة لأن الكنترول مو تخصصه وواضح أنه غير متمكن من المادة\nالكويزات : سهلة\nالمياجر: سؤاله يكون أصعب سؤال ومع هذا المياجر متوسطة المستوى ويمديك تاخذ فيها درجات كويسة\nالفاينلات : نفس المياجر وجابوا فيه كونسيبت 20%\nالقريد النهائي: بصراحة أعطى كل واحد أكثر من حقه في القريد ومدري هو بس سوا كذا ولا 401 في تساهل بالقريدات بشكل عام\nالصوت: يعني نص نص\nإضافات : عيبه الأساسي الشرح بالذات في 401 يمكن في مواد ثانية يكون أحسن، شغلة ثانية أنه في شوية شوفة نفس يعني مثلا هو أخذ الدكتوراه قبل أقل من 6 شهور وحاط اهتماماته البحثية في موقع القسم كذا: Catalyst Development & Characterization, Heterogeneous Catalysis, Photocatalysis, Reaction Engineering & Kinetics, Refining, Solar Thermal Energy, CO2 Capture & Sequestration (CCS), Mathematical Modeling, Numerical Simulation and Multi-Objective Optimizationâ€‹\n\nبالله متى مداه يسوي كل ذا؟! في وحدة من هذه المجالات أنا بنفسي سمعته يقول أنه ما يفهم فيها مرة.\n\nشغلة أخيرة أن الرجال واضح وتعامله جيد كل درجاتك تشوفها في البلاك بورد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1444373-che401", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/quddus-mohammad/172453/3", "user": "_3111", "ts": 1458327671000, "tid": 172453, "pn": 3}}]}', 1458327671000, 1794826845, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
